  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    memory = []
    for idx, trial in enumerate(trials):
        sig = trial['signature']
        ref = trial['reflection']
        succ = trial['success']
        entry = {'signature': sig, 'reflection': ref, 'success': succ, 'idx': idx}
        if not succ:
            found = None
            for i, e in enumerate(memory):
                if e['signature'] == sig and not e['success']:
                    found = i
                    break
            if found is not None:
                memory[found] = entry
            else:
                memory.append(entry)
        else:
            memory.append(entry)
    while len(memory) > capacity:
        failures = [e for e in memory if not e['success']]
        successes = [e for e in memory if e['success']]
        if successes:
            successes.sort(key=lambda x: (x['idx'], x['signature']))
            to_remove = successes[0]
        else:
            failures.sort(key=lambda x: (x['idx'], x['signature']))
            to_remove = failures[0]
        memory = [e for e in memory if e['idx'] != to_remove['idx']]
    memory.sort(key=lambda x: x['idx'])
    result = []
    for e in memory:
        result.append({'signature': e['signature'], 'reflection': e['reflection'], 'success': e['success']})
    return result"
